-- ============================================================
-- SGICO: Reset + 7 casos de prueba listos para comité
-- ============================================================
--
-- OBJETIVO: dejar la base limpia y cargar 7 casos completos para probar
--   el flujo del comité y los indicadores de impacto:
--     1. Naive           — Pulmón EGFR+       → Osimertinib (FLAURA)
--     2. Neoadyuvancia   — Mama triple neg.   → KEYNOTE-522
--     3. Adyuvancia      — Mama HER2+ residual→ T-DM1 (KATHERINE)
--     4. 1ª línea        — Pulmón PD-L1 60%   → Pembrolizumab + QT (KEYNOTE-189)
--     5. 1ª línea        — Gástrico HER2-     → Nivolumab + FOLFOX (CheckMate 649)
--     6. 2ª línea        — Colon RAS mutado   → FOLFIRI + aflibercept (VELOUR)
--     7. 2ª línea        — Mama HER2+ metast. → T-DXd (DESTINY-Breast03)
--
--   Todos quedan AGENDADOS (sin presentar) en un comité de tumor sólido el
--   jueves 12/11/2026: aparecen en Agenda y en Comités con «Presentar».
--   Pacientes ficticios, documentos CC 900000001 a 900000007.
--
-- ⚠️  BORRA DE FORMA PERMANENTE todos los pacientes, casos, actas,
--     seguimientos, desenlaces y sesiones de comité.
-- CONSERVA: catálogos (eps, sedes, médicos, gestores, protocolos),
--     miembros del comité y sus firmas, usuarios.
--
-- Ejecutar en: Supabase SQL Editor (una sola transacción)
-- ============================================================

BEGIN;

-- ── GUARDA — solo datos de prueba ──────────────────────────
-- Aborta si hay pacientes que no son de prueba (documento distinto de
-- 9000000xx). Para borrarlos de todas formas, agrega justo debajo de BEGIN:
--   SET LOCAL sgico.confirmo_reset = 'BORRAR-TODO';
DO $$
DECLARE v_reales int;
BEGIN
  SELECT count(*) INTO v_reales FROM pacientes WHERE documento NOT LIKE '9000000%';
  IF v_reales > 0 AND current_setting('sgico.confirmo_reset', true) IS DISTINCT FROM 'BORRAR-TODO' THEN
    RAISE EXCEPTION 'ABORT: hay % pacientes que no son de prueba. No se borró nada.', v_reales
      USING HINT = 'Si de verdad quieres borrarlos: SET LOCAL sgico.confirmo_reset = ''BORRAR-TODO''; debajo de BEGIN.';
  END IF;
END $$;

-- Permite borrar actas firmadas (bloqueadas desde la migración 023)
SET LOCAL sgico.mantenimiento = 'si';

-- ── PASO 1 — Reset del dominio clínico ─────────────────────
ALTER TABLE casos_comite DISABLE TRIGGER trg_caso_historial;
ALTER TABLE seguimientos DISABLE TRIGGER tr_siguiente_evaluacion;

DELETE FROM casos_historial;
DELETE FROM alertas;
DELETE FROM desenlaces;
DELETE FROM seguimientos;
DELETE FROM actas_comite;
DELETE FROM medicamentos;
DELETE FROM casos_comite;
DELETE FROM diagnosticos;
DELETE FROM pacientes;
DELETE FROM sesiones_comite;

ALTER SEQUENCE pacientes_id_seq        RESTART WITH 1;
ALTER SEQUENCE diagnosticos_id_seq     RESTART WITH 1;
ALTER SEQUENCE casos_comite_id_seq     RESTART WITH 1;
ALTER SEQUENCE seguimientos_id_seq     RESTART WITH 1;
ALTER SEQUENCE medicamentos_id_seq     RESTART WITH 1;
ALTER SEQUENCE alertas_id_seq          RESTART WITH 1;
ALTER SEQUENCE desenlaces_id_seq       RESTART WITH 1;
ALTER SEQUENCE casos_historial_id_seq  RESTART WITH 1;
ALTER SEQUENCE sesiones_comite_id_seq  RESTART WITH 1;

ALTER TABLE casos_comite ENABLE TRIGGER trg_caso_historial;
ALTER TABLE seguimientos ENABLE TRIGGER tr_siguiente_evaluacion;

-- ── PASO 2 — Comité y casos ────────────────────────────────
DO $$
DECLARE
  v_sesion int; v_pac int; v_diag int;
  v_sede int   := (SELECT id FROM sedes ORDER BY id LIMIT 1);
  v_gestor int := (SELECT id FROM gestores ORDER BY id LIMIT 1);
  v_eps int[]  := ARRAY(SELECT id FROM eps ORDER BY id);
  v_med int[]  := ARRAY(SELECT id FROM medicos ORDER BY id);
BEGIN
  IF cardinality(v_eps) = 0 THEN v_eps := ARRAY[NULL::int]; END IF;
  IF cardinality(v_med) = 0 THEN v_med := ARRAY[NULL::int]; END IF;

  INSERT INTO sesiones_comite (fecha, tipo_comite, notas)
  VALUES ('2026-11-12', 'tumor_solido', 'Comité de prueba: 7 casos para validar indicadores')
  RETURNING id INTO v_sesion;

