  VALUES (v_pac, v_sede, v_med[1 + 0 % cardinality(v_med)], v_gestor, (SELECT id FROM protocolos WHERE estudio_pivotal = 'FLAURA' AND activo ORDER BY id LIMIT 1), '2026-11-02', 'tumor_solido', 'normal', 'pendiente', '¿Se aprueba osimertinib en primera línea para adenocarcinoma de pulmón estadio IV con deleción del exón 19 de EGFR?', 'Paciente naive con mutación sensibilizante de EGFR. Osimertinib mostró superioridad en SLP y SG frente a TKI de primera generación (FLAURA) y es estándar de primera línea.', 'Osimertinib', NULL, 'naive', 'metastasica_1', true, 0, 1, 'Ninguna — paciente sin tratamiento previo | No ha recibido | No ha recibido | No ha recibido', NULL, 18500000, '{"actual": {"costo_ciclo": 0, "duracion_dias": 0, "pfs_meses": null, "os_meses": null}, "propuesto": {"costo_ciclo": 18500000, "duracion_dias": 28, "duracion": "hasta_progresion", "ciclos_esquema": null, "pfs_meses": 18.9, "os_meses": 38.6, "ciclos_pfs": 20.25, "total_pfs": 374625000}, "diferencial": {"diferencia_pfs": null, "ganancia_pfs_meses": null, "costo_por_mes_pfs_ganado": null, "es_naive": true, "motivo_sin_diferencial": "naive"}, "nota": "Costo del tratamiento: hasta la progresión (PFS), cuando se cambia de línea, o los ciclos del esquema en tratamientos de duración fija. La SG es solo referencia clínica y no entra en el costo."}'::jsonb, true, false, v_diag, 'Adenocarcinoma de pulmón estadio IV con mutación EGFR', true, 'Adenocarcinoma de pulmón', true, 'TTF-1 positivo, napsina A positivo, CK7 positivo', 'IV', 'T2bN2M1b', '2026-10-01', 'EGFR exón 19 deleción: positivo · ALK: negativo · ROS1: negativo · PD-L1 TPS 20%', '1', 3, 'Peso 68 kg, talla 1,70 m. Tos seca y disnea de grandes esfuerzos. Sin focalización neurológica.', 'HTA controlada', 'Antecedente negativo', 'exfumador', 'social', 'Losartán 50 mg/día', 'TAC tórax-abdomen (07/10/2026): masa LSD 4,8 cm, adenopatías mediastinales, metástasis suprarrenal izquierda única. RM cerebral (10/10/2026): sin lesiones.', 'Hb 13,1 · Leu 7.200 · 