-- ── PASO 3 — Verificación ──────────────────────────────────
DO $$
DECLARE v_cas int; v_sinprot int; v_off int;
BEGIN
  SELECT COUNT(*) INTO v_cas FROM casos_comite WHERE presentado = false AND sesion_id IS NOT NULL AND decision = 'pendiente';
  SELECT COUNT(*) INTO v_sinprot FROM casos_comite WHERE protocolo_id IS NULL;
  SELECT COUNT(*) INTO v_off FROM pg_trigger
   WHERE tgname IN ('trg_caso_historial','tr_siguiente_evaluacion') AND tgenabled = 'D';
  IF v_cas <> 7 THEN RAISE EXCEPTION 'ABORT: se esperaban 7 casos agendados y hay %', v_cas; END IF;
  IF v_off > 0 THEN RAISE EXCEPTION 'ABORT: % triggers quedaron apagados', v_off; END IF;
  RAISE NOTICE '════════ OK: base limpia y 7 casos agendados para el comité del 12/11/2026 ════════';
  IF v_sinprot > 0 THEN
    RAISE NOTICE 'Aviso: % caso(s) sin protocolo del catálogo (el tratamiento propuesto queda como texto)', v_sinprot;
  END IF;
END $$;

COMMIT;

-- Resumen para revisar después de ejecutar
SELECT c.id, p.nombre, c.contexto_actual, c.contexto_propuesto, c.tratamiento_propuesto,
       pr.estudio_pivotal AS protocolo, c.costo_previo, c.costo_estimado, s.fecha AS comite
  FROM casos_comite c
  JOIN pacientes p ON p.id = c.paciente_id
  JOIN sesiones_comite s ON s.id = c.sesion_id
  LEFT JOIN protocolos pr ON pr.id = c.protocolo_id
 ORDER BY c.id;
